const caseData = items[0]?.json ?? {};
const emailResponse = items[1]?.json ?? {};
const feedResponse = items[2]?.json ?? {};
const taskResponse = items[3]?.json ?? {};

/**
 * Configuration
 */
const MAX_EMAILS = 30;
const MAX_FEED_ITEMS = 30;
const MAX_TASKS = 30;

const MAX_DESCRIPTION_LENGTH = 8000;
const MAX_MESSAGE_LENGTH = 4000;
const MAX_TASK_DESCRIPTION_LENGTH = 3000;

/**
 * Convert a value to a normalized string.
 */
function normalizeText(value, maxLength = 4000) {
  if (value === null || value === undefined) {
    return null;
  }

  let text = String(value)
    // Decode a few common HTML entities from Salesforce email content.
    .replace(/&nbsp;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">")
    .replace(/&#39;/gi, "'")
    .replace(/&quot;/gi, '"')

    // Remove Salesforce email thread tokens.
    .replace(/thread::[^\s]+::/gi, "")

    // Remove image and tracking URLs.
    .replace(
      /https?:\/\/[^\s\]]*(?:ImageServer|servlet\.ImageServer)[^\s\]]*/gi,
      ""
    )

    // Normalize whitespace.
    .replace(/\r\n/g, "\n")
    .replace(/\r/g, "\n")
    .replace(/[ \t]+/g, " ")
    .replace(/\n{3,}/g, "\n\n")
    .trim();

  if (!text) {
    return null;
  }

  if (text.length > maxLength) {
    text = `${text.slice(0, maxLength).trim()}…`;
  }

  return text;
}

/**
 * Remove quoted email history so each email contains only the newest message.
 */
function removeQuotedHistory(value) {
  const text = normalizeText(value, 20000);

  if (!text) {
    return null;
  }

  const separators = [
    "--------------- Original Message ---------------",
    "-----Original Message-----",
    "\nFrom:",
    "\nSent:",
    "\nOn "
  ];

  let cutoff = text.length;

  for (const separator of separators) {
    const index = text.indexOf(separator);

    if (index >= 0 && index < cutoff) {
      cutoff = index;
    }
  }

  return normalizeText(text.slice(0, cutoff), MAX_MESSAGE_LENGTH);
}

/**
 * Replace unnecessary personal/contact details in free text.
 *
 * Set these replacements according to your privacy requirements.
 */
function redactSensitiveData(value, maxLength = 4000) {
  const text = normalizeText(value, maxLength);

  if (!text) {
    return null;
  }

  return text
    // Email addresses
    .replace(
      /\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/gi,
      "[email removed]"
    )

    // Common North American phone formats
    .replace(
      /(?:\+?1[\s.-]?)?(?:\(\d{3}\)|\d{3})[\s.-]?\d{3}[\s.-]?\d{4}\b/g,
      "[phone removed]"
    )

    // Salesforce 15- or 18-character IDs
    .replace(/\b[a-zA-Z0-9]{15}(?:[a-zA-Z0-9]{3})?\b/g, "[record id removed]")

    // Collapse whitespace again after replacements.
    .replace(/[ \t]+/g, " ")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

/**
 * Return null instead of empty strings.
 */
function cleanValue(value, maxLength = 4000) {
  return redactSensitiveData(value, maxLength) || null;
}

/**
 * Normalize Salesforce dates into ISO strings.
 */
function normalizeDate(value) {
  if (!value) {
    return null;
  }

  const date = new Date(value);

  return Number.isNaN(date.getTime()) ? null : date.toISOString();
}

/**
 * Infer a standardized sender category.
 */
function getSenderType(record) {
  if (record?.Incoming === true) {
    return "customer";
  }

  if (record?.Incoming === false) {
    return "support";
  }

  return "unknown";
}

/**
 * Normalize email messages.
 */
const emails = (emailResponse.records ?? [])
  .map((email) => ({
    date: normalizeDate(email.MessageDate ?? email.CreatedDate),
    direction: email.Incoming === true ? "inbound" : "outbound",
    senderType: getSenderType(email),
    senderName: cleanValue(email.FromName, 200),
    subject: cleanValue(email.Subject, 500),
    body: redactSensitiveData(
      removeQuotedHistory(email.TextBody ?? email.HtmlBody),
      MAX_MESSAGE_LENGTH
    ),
    hasAttachment: Boolean(email.HasAttachment)
  }))
  .filter((email) => email.body || email.subject)
  .sort((a, b) => {
    const first = a.date ? Date.parse(a.date) : 0;
    const second = b.date ? Date.parse(b.date) : 0;
    return first - second;
  })
  .slice(-MAX_EMAILS);

/**
 * Normalize feed items.
 *
 * Update field fallbacks if your Salesforce FeedItem query returns
 * different field names.
 */
