  }

  if (text.length > maxLength) {
    text = `${text.slice(0, maxLength).trim()}…`;
  }

  return text;
}

/**
 * Remove quoted email history so each email contains only the newest message.
 */
function removeQuotedHistory(value) {
  const text = normalizeText(value, 20000);

  if (!text) {
    return null;
  }

  const separators = [
    "--------------- Original Message ---------------",
    "-----Original Message-----",
    "\nFrom:",
    "\nSent:",
    "\nOn "
  ];

  let cutoff = text.length;

  for (const separator of separators) {
    const index = text.indexOf(separator);

    if (index >= 0 && index < cutoff) {
      cutoff = index;
    }
  }

  return normalizeText(text.slice(0, cutoff), MAX_MESSAGE_LENGTH);
}

/**
 * Replace unnecessary personal/contact details in free text.
 *
 * Set these replacements according to your privacy requirements.
 */
function redactSensitiveData(value, maxLength = 4000) {
  const text = normalizeText(value, maxLength);

  if (!text) {
    return null;
  }

  return text
    // Email addresses
    .replace(
      /\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/gi,
      "[email removed]"
    )

    // Common North American phone formats
    .replace(
      /(?:\+?1[\s.-]?)?(?:\(\d{3}\)|\d{3})[\s.-]?\d{3}[\s.-]?\d{4}\b/g,
      "[phone removed]"
    )

    // Salesforce 15- or 18-character IDs
    .replace(/\b[a-zA-Z0-9]{15}(?:[a-zA-Z0-9]{3})?\b/g, "[record id removed]")

    // Collapse whitespace again after replacements.
    .replace(/[ \t]+/g, " ")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

/**
 * Return null instead of empty strings.
 */
function cleanValue(value, maxLength = 4000) {
  return redactSensitiveData(value, maxLength) || null;
}

/**
 * Normalize Salesforce dates into ISO strings.
 */
function normalizeDate(value) {
  if (!value) {
    return null;
  }

  const date = new Date(value);

  return Number.isNaN(date.getTime()) ? null : date.toISOString();
}

/**
 * Infer a standardized sender category.
 */
function getSenderType(record) {
  if (record?.Incoming === true) {
    return "customer";
  }

  if (record?.Incoming === false) {
    return "support";
  }

  return "unknown";
}

/**
 * Normalize email messages.
 */
const emails = (emailResponse.records ?? [])
  .map((email) => ({
    date: normalizeDate(email.MessageDate ?? email.CreatedDate),
    direction: email.Incoming === true ? "inbound" : "outbound",
    senderType: getSenderType(email),
    senderName: cleanValue(email.FromName, 200),
    subject: cleanValue(email.Subject, 500),
    body: redactSensitiveData(
      removeQuotedHistory(email.TextBody ?? email.HtmlBody),
      MAX_MESSAGE_LENGTH
    ),
    hasAttachment: Boolean(email.HasAttachment)
  }))
  .filter((email) => email.body || email.subject)
  .sort((a, b) => {
    const first = a.date ? Date.parse(a.date) : 0;
    const second = b.date ? Date.parse(b.date) : 0;
    return first - second;
  })
  .slice(-MAX_EMAILS);

/**
 * Normalize feed items.
 *
 * Update field fallbacks if your Salesforce FeedItem query returns
 * different field names.
 */
const feedItems = (feedResponse.records ?? [])
  .map((feed) => ({
    date: normalizeDate(feed.CreatedDate),
    type: cleanValue(feed.Type, 100),
    author: cleanValue(
      feed.CreatedBy?.Name ??
        feed.CreatedByName ??
        feed.InsertedBy?.Name,
      200
    ),
    body: cleanValue(
      feed.Body ??
        feed.CommentBody ??
        feed.TextBody,
      MAX_MESSAGE_LENGTH
    ),
    visibility: cleanValue(feed.Visibility, 100)
  }))
  .filter((feed) => feed.body)
  .sort((a, b) => {
    const first = a.date ? Date.parse(a.date) : 0;
    const second = b.date ? Date.parse(b.date) : 0;
    return first - second;
  })
  .slice(-MAX_FEED_ITEMS);

/**
 * Normalize tasks.
 */
const tasks = (taskResponse.records ?? [])
  .map((task) => ({
    date: normalizeDate(
      task.ActivityDate ??
        task.CompletedDateTime ??
        task.CreatedDate
    ),
    subject: cleanValue(task.Subject, 500),
    status: cleanValue(task.Status, 100),
    type: cleanValue(task.TaskSubtype ?? task.Type, 100),
    description: cleanValue(
      removeQuotedHistory(task.Description),
      MAX_TASK_DESCRIPTION_LENGTH
    ),
    completed: Boolean(
      task.IsClosed ||
      task.Status === "Completed"
    )
  }))
  .filter((task) => task.subject || task.description)
  .sort((a, b) => {
    const first = a.date ? Date.parse(a.date) : 0;
    const second = b.date ? Date.parse(b.date) : 0;
    return first - second;
  })
  .slice(-MAX_TASKS);

/**
 * Deliberately allowlist only fields useful for resolution analysis.
 */
const normalizedCase = {
  id: caseData.Id,
  caseNumber: cleanValue(caseData.CaseNumber, 100),
  subject: cleanValue(caseData.Subject, 1000),
  description: cleanValue(
    caseData.Description,
    MAX_DESCRIPTION_LENGTH
  ),

  status: cleanValue(caseData.Status, 200),
  closeReason: cleanValue(
    caseData.Reason ??
      caseData.Case_Outcome__c ??
      caseData.Resolution_Type__c,
    500
  ),

  priority: cleanValue(caseData.Priority, 100),
  severity: cleanValue(caseData.Severity__c, 100),
  origin: cleanValue(caseData.Origin, 100),
  caseType: cleanValue(caseData.Type, 100),

  accountName: cleanValue(accountResponse.records?.[0]?.Name, 300),
  accountType: cleanValue(accountResponse.records?.[0]?.Type, 100),
  caseResearch: cleanValue(caseData.Case_Research__c, 4000),

  product: cleanValue(
    caseData.Support_Product__c ??
      caseData.Support_Product_Text__c,
    300
  ),
  productArea: cleanValue(caseData.Product_Area__c, 300),
  businessUnit: cleanValue(caseData.Business_Unit__c, 300),
  adoWorkItemId: cleanValue(caseData.ADO_WorkItem_ID__c, 200),
  devIssueNumber: cleanValue(caseData.Issue__c, 200),
  supportVertical: cleanValue(caseData.Support_Vertical__c, 300),
  environment: cleanValue(caseData.Environment__c, 500),
  version: cleanValue(caseData.Version__c, 200),

  team: cleanValue(caseData.Team__c, 200),
  ownerName: cleanValue(
    caseData.Task_Assigned_To__c ??
      caseData.Owner?.Name,
    200
  ),

  stepsToReproduce: cleanValue(
    caseData.Steps_to_Reproduce_Text__c ??
      caseData.Steps_to_Reproduce__c,
    MAX_DESCRIPTION_LENGTH
  ),

  rootCause: cleanValue(caseData.Root_Cause__c, 4000),
  engineeringDescription: cleanValue(
    caseData.Engineering_Description_Text__c ??
      caseData.Engineering_Description__c,
    4000
  ),
  engineeringResolution: cleanValue(
    caseData.Engineering_Resolution__c,
    4000
  ),
  engineeringStatus: cleanValue(
    caseData.Engineering_Status__c,
    200
  ),
  fixedInVersion: cleanValue(
    caseData.Engineering_Fixed_in_Version__c,
    200
  ),

  existingResolutionSummary: cleanValue(
