    caseData.IsEscalated ||
      caseData.Is_Customer_Escalated__c
  ),
  wasReopened: Boolean(
    caseData.Is_Reopened_Case__c ||
      Number(caseData.Reopen_Count__c ?? 0) > 0
  )
};

/**
 * Remove null fields from an object while preserving false and zero.
 */
function removeNullFields(object) {
  return Object.fromEntries(
    Object.entries(object).filter(
      ([, value]) =>
        value !== null &&
        value !== undefined &&
        value !== ""
    )
  );
}

const payload = {
  schemaVersion: "1.0",
  purpose: "case_resolution_summary",
  case: removeNullFields(normalizedCase),
  timeline: {
    emails,
    feedItems,
    tasks
  },
  recordCounts: {
    emails: emails.length,
    feedItems: feedItems.length,
    tasks: tasks.length
  }
};

return [
  {
    json: {
      ok: true,
      payload
    }
  }
];

const request = $input.first().json;
const body = request.body || {};
const errors = [];

const cleanString = (value) => typeof value === 'string' ? value.trim() : '';
const caseNumber = cleanString(body.caseNumber);
const summary = cleanString(body.summary);

if (!caseNumber) errors.push('caseNumber is required');
if (!summary) errors.push('summary is required');
if (body.resolutionSteps !== undefined && !Array.isArray(body.resolutionSteps)) {
  errors.push('resolutionSteps must be an array of strings');
}

if (errors.length > 0) {
  return [{
    json: {
      ok: false,
      statusCode: 400,
      error: 'Validation failed',
      details: errors
    }
  }];
}

const store = $getWorkflowStaticData('global');
store.caseResolutionSummaries = store.caseResolutionSummaries || {};

const now = new Date().toISOString();
const record = {
  ok: true,
  action: 'sendCaseResolutionSummary',
  caseNumber,
  summary,
  resolutionStatus: cleanString(body.resolutionStatus) || 'resolved',
  customerImpact: cleanString(body.customerImpact) || undefined,
  rootCause: cleanString(body.rootCause) || undefined,
  resolutionSteps: Array.isArray(body.resolutionSteps) ? body.resolutionSteps.map(String).filter(Boolean) : [],
  resolvedBy: cleanString(body.resolvedBy) || undefined,
  resolvedAt: cleanString(body.resolvedAt) || now,
  sourceSystem: cleanString(body.sourceSystem) || undefined,
  metadata: body.metadata && typeof body.metadata === 'object' && !Array.isArray(body.metadata) ? body.metadata : {},
  storedAt: now
};

store.caseResolutionSummaries[caseNumber] = record;

return [{ json: record }];
